// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    uint256 immutable numCalls;

    function setUp() public {
        c = new SimpleWallet();
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint64).max);
        uint256 countBefore = c.depositsCount();
        vm.deal(address(this), amount * 3);
        for (uint256 i = 0; i < 3; i++) {
            (bool ok, ) = address(c).call{value: amount}("");
            require(ok, "receive failed");
        }
        uint256 countAfter = c.depositsCount();
        assertEq(countAfter, countBefore + 3);
    }
}
